mapper.update:
UPDATE shopping_cart
SET number = #{number}
WHERE id = #{id};

mapper.delete:
DELETE FROM shopping_cart
WHERE id = #{id}
  AND number = #{number}
  AND user_id = #{userId}
  AND (dish_id IS NOT NULL OR setmeal_id IS NOT NULL)

mapper.select:
SELECT *
FROM shopping_cart


    AND user_id = #{userId}


    AND dish_id = #{dishId}


    AND dish_flavor = #{dishFlavor}


    AND setmeal_id = #{setmealId}
